function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#2a1f14', P='#d4cbb4', PL='#f0e8d6', PD='#a89878', Ink='#4a3080';
  px(16,12,32,44,O); px(18,14,28,40,P);
  px(18,14,28,2,PL); px(18,52,28,2,PD);
  px(22,20,20,2,Ink); px(22,26,16,2,Ink); px(22,32,18,2,Ink);
  px(22,38,12,2,Ink); px(36,18,4,4,O);
}
